use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let frame = frames.get(index: i);
        let value = match feed.decode(frame: frame) {
            Some(v) => v,
            None => 0,
        };
        total = total + value;
        i = i + 1;
    }
    feed.emit(io: io, total: total)?;
    return Ok(unit);
}
```

